package com.pulsefit.attendanceservice.repo; import com.pulsefit.attendanceservice.entity.Attendance; import org.springframework.data.jpa.repository.JpaRepository; import java.time.LocalDateTime; import java.util.*; public interface AttendanceRepository extends JpaRepository<Attendance,Long>{List<Attendance> findByMemberIdOrderByCheckInTimeDesc(Long id); List<Attendance> findByCheckInTimeBetweenOrderByCheckInTimeDesc(LocalDateTime a,LocalDateTime b); List<Attendance> findByFacilityOrderByCheckInTimeDesc(String facility);}
